using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CityMobileLODIntegration{static CityMobileLODIntegration(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CityMobileLODIntegration.request"))return;File.Delete("CityMobileLODIntegration.request");try{Run();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/MobileOptimization/LODIntegration.txt",e.ToString());Debug.LogException(e);}}
static int Repair(GameObject root,StringBuilder log){int changes=0;var lods=root.GetComponentsInChildren<LODGroup>(true);foreach(var g in lods.OrderByDescending(g=>Depth(g.transform))){if(!g)continue;var mine=new HashSet<Renderer>(g.GetLODs().SelectMany(l=>l.renderers).Where(r=>r));var parent=g.transform.parent;LODGroup owner=null;while(parent){var p=parent.GetComponent<LODGroup>();if(p&&p.GetLODs().SelectMany(l=>l.renderers).Any(r=>r&&mine.Contains(r))){owner=p;break;}parent=parent.parent;}if(!owner)continue;foreach(var r in mine.Where(r=>r.name.StartsWith("Mobile LOD"))){r.gameObject.SetActive(false);PrefabUtility.RecordPrefabInstancePropertyModifications(r.gameObject);}UnityEngine.Object.DestroyImmediate(g);changes++;}
foreach(var g in root.GetComponentsInChildren<LODGroup>(true)){var levels=g.GetLODs();bool dirty=false;for(int i=0;i<levels.Length;i++)if(levels[i].renderers.Any(r=>!r)){var valid=levels[i].renderers.Where(r=>r).ToArray();if(valid.Length==0){var own=g.GetComponent<MeshRenderer>();valid=own?new Renderer[]{own}:levels.SelectMany(l=>l.renderers).Where(r=>r).Distinct().ToArray();}levels[i].renderers=valid;dirty=true;}if(dirty){g.SetLODs(levels);EditorUtility.SetDirty(g);PrefabUtility.RecordPrefabInstancePropertyModifications(g);changes++;}}
var controlled=new HashSet<Renderer>(root.GetComponentsInChildren<LODGroup>(true).SelectMany(g=>g.GetLODs().SelectMany(l=>l.renderers)).Where(r=>r));foreach(var r in root.GetComponentsInChildren<MeshRenderer>(true).Where(r=>r.name.StartsWith("Mobile LOD")&&!controlled.Contains(r))){if(!r.gameObject.activeSelf)continue;r.gameObject.SetActive(false);PrefabUtility.RecordPrefabInstancePropertyModifications(r.gameObject);changes++;}return changes;}
static int Depth(Transform t){int n=0;while(t.parent){n++;t=t.parent;}return n;}
static void Run(){var sc=SceneManager.GetActiveScene();var log=new StringBuilder();var roots=sc.GetRootGameObjects();var paths=new HashSet<string>();foreach(var g in roots.SelectMany(r=>r.GetComponentsInChildren<LODGroup>(true))){bool issue=g.GetLODs().Any(l=>l.renderers.Any(r=>!r));if(g.transform.parent){var parent=g.transform.parent.GetComponentsInParent<LODGroup>(true).FirstOrDefault(p=>p!=g&&p.GetLODs().SelectMany(l=>l.renderers).Any(r=>r&&g.GetLODs().SelectMany(a=>a.renderers).Contains(r)));if(parent){string p=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(parent.gameObject);if(!string.IsNullOrEmpty(p))paths.Add(p);}}if(issue){string p=PrefabUtility.GetPrefabAssetPathOfNearestInstanceRoot(g.gameObject);if(!string.IsNullOrEmpty(p))paths.Add(p);}}
foreach(string path in paths){CityMobileOptimizationBuild.Backup(path);var content=PrefabUtility.LoadPrefabContents(path);try{int n=Repair(content,log);if(n>0){PrefabUtility.SaveAsPrefabAsset(content,path);log.AppendLine("SOURCE REPAIRED "+path+" changes="+n);}}finally{PrefabUtility.UnloadPrefabContents(content);}}
int fixedCount=0;foreach(var root in sc.GetRootGameObjects())fixedCount+=Repair(root,log);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(sc);EditorSceneManager.SaveScene(sc);log.AppendLine("Scene integration repairs="+fixedCount+"; existing outer LOD systems retained. Redundant inherited inner LODs removed; orphan new far renderers disabled; null old renderer references repaired.");File.WriteAllText("FinalEnvironmentRoadReview/MobileOptimization/LODIntegration.txt",log.ToString());File.WriteAllText("CityMobileVerify.request","run");}}
